using System.Collections;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ChainedChantingAction", menuName = "Data/Battle/Battle Actions/Sothis/ChainedChanting Action")]
public class ChainedChantingAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private ChantingAction chantingAction;

	[SerializeField]
	protected FloatReference delayBetweenCorruptPurifyFloatReference;

	[SerializeField]
	private SoulHeat soulHeat;

	[SerializeField]
	private bool resetSoulHeat;

	public float delayBetweenCorruptPurify => delayBetweenCorruptPurifyFloatReference.Value;

	public bool ResetSoulHeat => resetSoulHeat;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return GetTimesAmount() > 0;
	}

	public int GetTimesAmount()
	{
		return Mathf.FloorToInt((float)soulHeat.SoulHeatCounter / 2f);
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(SingleTargetCast(target, source));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
	}

	private IEnumerator SingleTargetCast(GameObject target, GameObject source)
	{
		yield return InvokeAlternatives.WaitOneFrame();
		int timesAmount = GetTimesAmount();
		for (int i = 0; i < timesAmount; i++)
		{
			chantingAction.CastTarget(target, source);
			yield return new WaitForSeconds(delayBetweenCorruptPurify);
		}
		if (resetSoulHeat)
		{
			soulHeat.ResetSoulHeat();
		}
	}
}
